// ENGINE-DAILY plan (n8n Code node). Writes nothing itself: returns one item { summary, data (batchUpdate ranges), appends }.
const MODE = $("Mode").first().json;
const DRY = MODE.dry !== false;          // true = report only
const MAX_DROPS = Number(MODE.max_drops) || 300;     // guard: rows paused in one run
const MAX_APPENDS = Number(MODE.max_appends) || 400; // guard: new PIPELINE rows in one run
const HORIZON_WEEKDAYS = 30;      // how far ahead new rows may be dated
const CAP_DAY = 2, CAP_WEEK = 5, CAP_OWNER_DAY = 20;
const MEET_STOP = 7; // user 18 Sep: startups with this many meetings or more get no new shares; their queued rows are paused
const MEET_NA = 'PAUSED - 7+ meetings (user 18 Sep)';
// user 22 Sep: the HOT deals (Q4 close push) are exempt from the meeting-count pause AND get priority for send dates
// 23 Sep: MindWox promoted from the middle desk (Prana/AWE/Enzia/Faad all live); CLIKD kept as well on the user's call, so 11 not 10
const HOT = ['spintly', 'boncuisine', 'eosnox', 'hyrgpt', 'talentrecruit', 'hoora', 'clikd', 'mindwox', 'mentorcloud', 'roadathena', 'learningpad'];
function isHot(name) { return HOT.indexOf(nz(name)) >= 0; }
const MEET_EXEMPT = HOT.slice(); // was ['clikd'] (user 19 Sep); all hot deals exempt from 22 Sep (user lifted the pause)
const NO_AUTO_PAIRS = ['spintly|gvfl','clikd|udyatventures']; // user 19 Sep: Udyat passed on CLIKD 3 Sep; no automatic re-share - a hand-written re-engage note goes in November
// 28 Sep 2026: Aditya REMOVED the meeting-count pause - "i remove this pause now and hot deals will get special priority."
// Why: Springbase.ai was blocked from every new investor on a row reading 'PAUSED - 8+ meetings' while the calendars showed
// THREE investor events, all with ONE investor (Suvan) who wanted advisory equity and never intended to invest. The rule froze
// a startup out of the market precisely because it had been busy failing.
// MEET_STOP / MEET_NA / MEET_EXEMPT are deliberately KEPT, not deleted: MEET_PAUSED_RE below still has to recognise the wording
// already written into 322 rows, and a reader needs to see why the dead code is dead. DO NOT wire them back into a gate.
// MEET_EXEMPT is now inert by definition - hot deals were exempt from a rule that no longer exists. Hot priority lives entirely
// in Part B0 (hot rows take the earliest dates in their inbox) and the hot pull-forward, neither of which ever used this rule.
const MEET_PAUSED_RE = /^PAUSED - \d+\+ meetings/; // matches both wordings in the sheet: 'PAUSED - 7+ meetings (user 18 Sep)' (207 rows) and 'PAUSED - 8+ meetings (user 18 Sep)' (115 rows)
function meetStop(name) { return false; }
const POC_OWNER = { iimaventures: 'Chaman' }; // investors who asked for ONE point of contact at Sidana (IIMA 18 Sep)
function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const vr = $('GET pilot').first().json.valueRanges || [];
const crit = (vr[0] || {}).values || [], prof = (vr[1] || {}).values || [], pipe = (vr[2] || {}).values || [], invs = (vr[3] || {}).values || [], sts = (vr[4] || {}).values || [];
const grid = $('GET meetings').first().json.values || [];
const trk = $('GET tracker').first().json.values || [];
if (crit.length < 200 || prof.length < 50 || pipe.length < 5000 || invs.length < 150 || sts.length < 40) { throw new Error('ABORT short read ' + [crit.length, prof.length, pipe.length, invs.length, sts.length].join('/')); }
function objs(rows) { const h = (rows[0] || []).map(s); return rows.slice(1).map(function (r) { const o = {}; h.forEach(function (k, i) { o[k] = r[i] === undefined ? '' : r[i]; }); return o; }); }
const C = objs(crit), SP = objs(prof), INV = objs(invs), ST = objs(sts);
// ===== ENGINE CORE v2 (identical to engine-core.js) =====
const LADDER = ['PRE_SEED', 'SEED', 'TRACTION', 'PRE_SERIES_A', 'SERIES_A', 'SERIES_B', 'SERIES_C_PLUS'];
function list(v) { if (Array.isArray(v)) { return v.map(function (x) { return String(x).trim(); }).filter(Boolean); } return String(v == null ? '' : v).split(/[,;|]/).map(function (x) { return x.trim(); }).filter(Boolean); }
function num(v) { if (v === null || v === undefined || v === '') { return null; } const n = Number(v); return isFinite(n) ? n : null; }
function yes(v) { return /^y(es)?$/i.test(String(v == null ? '' : v).trim()); }
function evaluate(inv, st, ctx) {
  const gates = []; function gate(name, ok, why) { gates.push({ gate: name, ok: ok, why: why }); }
  const meetings = ctx && typeof ctx.meetings === 'number' ? ctx.meetings : 0;
  const status = String(inv.status || '').toUpperCase(); gate('investor_active', status === 'ACTIVE', 'status ' + (status || 'blank'));
  gate('startup_active', yes(st.active), 'startup active=' + st.active);
  const sIn = list(inv.sectors_in), sEx = list(inv.sectors_excluded), sSt = list(st.sector_codes);
  const excludedHit = sSt.filter(function (c) { return sEx.indexOf(c) >= 0; });
  if (excludedHit.length) { gate('sector', false, 'startup sector ' + excludedHit.join('/') + ' is EXCLUDED by investor'); }
  else if (String(inv.sector_mode || '').toUpperCase() === 'AGNOSTIC') { gate('sector', true, 'investor sector-agnostic (sector waived ONLY; every other gate below still applies - Aditya 1 Oct 2026)'); }
  else { const overlap = sSt.filter(function (c) { return sIn.indexOf(c) >= 0; });
    if (!overlap.length) { gate('sector', false, 'no overlap: startup ' + sSt.join('/') + ' vs investor ' + (sIn.join('/') || 'none')); }
    else if (overlap.indexOf(sSt[0]) >= 0) { gate('sector', true, 'overlap ' + overlap.join('/')); }
    else {
      // Only a SECONDARY startup tag overlaps (precision rule 17 Sep): a corporate VC needs the startup's main sector;
      // a horizontal tag (AI / IoT / consumer app / SaaS) counts only for funds that also back software.
      const HORIZ = ['AI_APPLIED_ENTERPRISE', 'IOT_SMART_HARDWARE', 'CONSUMER_TECH_APP', 'SAAS_ENTERPRISE'];
      const cvc = String(inv.investor_type || '').toUpperCase() === 'CVC';
      const vertical = overlap.filter(function (c) { return HORIZ.indexOf(c) < 0; });
      const ok2 = !cvc && (vertical.length > 0 || sIn.indexOf('SAAS_ENTERPRISE') >= 0);
      gate('sector', ok2, ok2 ? 'secondary overlap ' + overlap.join('/') : 'only secondary tag ' + overlap.join('/') + ' overlaps; main sector ' + sSt[0] + ' not on investor list' + (cvc ? ' (corporate VC needs the main sector)' : ' (fund does not back software)'));
    } }
  const mIn = list(inv.models_in), mEx = list(inv.models_excluded), m = String(st.business_model || '');
  if (mEx.indexOf(m) >= 0) { gate('business_model', false, m + ' excluded by investor'); }
  else if (!mIn.length || mIn.indexOf('ANY') >= 0) { gate('business_model', true, 'any model'); }
  else { gate('business_model', mIn.indexOf(m) >= 0, mIn.indexOf(m) >= 0 ? m + ' allowed' : m + ' not in ' + mIn.join('/')); }
  // ---- STAGE: STRICT. Aditya, 1 Oct 2026: "if the company is series a then send it to only series a investors thats it."
  // The one-rung tolerance and the Series-A-and-later exception are BOTH removed. They were the single largest source of
  // mismatch: of 1,192 mismatched rows found in the 1 Oct audit, 461 failed on stage. Alt F Coworking at SERIES_A reached
  // seven funds whose band stops at PRE_SERIES_A because dist was 1; IN44 got Spintly on 28 Sep through the exception,
  // which is what made him ask us to stop sending. A stage band is now a hard boundary in both directions.
  let stageOffBy = 0;
  const si = LADDER.indexOf(String(st.stage_code || '')), lo = LADDER.indexOf(String(inv.stage_min || '')), hi = LADDER.indexOf(String(inv.stage_max || ''));
  if (si < 0) { gate('stage', false, 'startup stage missing'); }
  else if (lo < 0 || hi < 0) { gate('stage', false, 'investor stage missing (ON HOLD rule)'); }
  else if (si >= lo && si <= hi) { gate('stage', true, st.stage_code + ' inside ' + inv.stage_min + '..' + inv.stage_max); }
  else { const dist = si < lo ? lo - si : si - hi; gate('stage', false, st.stage_code + ' is ' + dist + ' rung(s) outside ' + inv.stage_min + '..' + inv.stage_max + ' (STRICT, no tolerance - Aditya 1 Oct 2026)'); }
  const cmin = num(inv.cheque_min_cr), raise = num(st.raise_cr);
  if (cmin === null) { gate('cheque', true, 'no minimum on file'); } else if (raise === null) { gate('cheque', false, 'startup raise unknown'); } else { gate('cheque', raise >= cmin, 'raise ' + raise + ' Cr vs min cheque ' + cmin + ' Cr'); }
  // ---- CHEQUE CEILING (Aditya, 1 Oct 2026). A fund that will not join a round above a certain size must stop
  // receiving rounds above it. IN44 is the case that prompted this: round_max 10 Cr, and he was sent Spintly on
  // 28 Sep, which is what made him ask us to stop.
  // FAILS OPEN. Only 1 of 303 investors has a ceiling on file, so a missing value MUST mean 'no ceiling known',
  // never 'ceiling of zero'. Treating blank as a limit would silently mute the entire book.
  // Only round_max_cr gates. A cheque_max or lead_max does not disqualify: an investor whose largest cheque is
  // 1.1 Cr can still take 1.1 Cr of a 25 Cr round. Only a round they will not enter at all is a hard no.
  const rmax = num(inv.round_max_cr);
  if (rmax !== null && raise !== null) { gate('round_ceiling', raise <= rmax, 'raise ' + raise + ' Cr vs max round size ' + rmax + ' Cr the investor will join'); }
  const amin = num(inv.arr_min_cr), arr = num(st.arr_cr);
  if (amin !== null) { if (arr === null) { gate('arr_bar', false, 'needs ARR ' + (yes(inv.arr_min_strict) ? '>' : '>=') + ' ' + amin + ' Cr, startup revenue unknown'); } else { const ok = yes(inv.arr_min_strict) ? arr > amin : arr >= amin; gate('arr_bar', ok, 'ARR ' + arr + ' Cr vs ' + (yes(inv.arr_min_strict) ? '>' : '>=') + ' ' + amin + ' Cr'); } }
  if (yes(inv.revenue_required)) { gate('revenue_required', arr !== null && arr > 0, arr === null ? 'revenue unknown' : 'ARR ' + arr + ' Cr'); }
  if (yes(inv.women_only)) { gate('women_only', yes(st.women), 'woman in cap table=' + st.women); }
  else if (String(inv.women_only || '').trim().toUpperCase() === 'DEEPTECH') { const DT = ['AI_FOUNDATIONAL', 'SEMICONDUCTOR_ELECTRONICS', 'SPACETECH', 'DEFENCE_AEROSPACE', 'BIOTECH_PHARMA', 'MEDTECH_DEVICES', 'IOT_SMART_HARDWARE', 'DATA_INFRA_DEVTOOLS']; const dt = sSt.filter(function (x) { return DT.indexOf(x) >= 0; }); if (dt.length) { gate('women_only', yes(st.women), 'deep-tech startup (' + dt.join('/') + ') needs a woman in cap table; women=' + st.women); } } // user 22 Sep (Colossa): women required only for deep tech
  if (yes(inv.excludes_jain_sensitive)) { gate('jain_exclusion', !yes(st.jain_sensitive), 'jain_sensitive=' + st.jain_sensitive); }
  const scope = list(String(inv.geography_scope || 'INDIA').toUpperCase());
  if (scope.indexOf('GLOBAL') < 0 && scope.indexOf('ANY') < 0) {
    const g = String(st.geography || '').toLowerCase();
    const REGION = { INDIA: /india|bharat/, SEA: /indonesia|singapore|malaysia|vietnam|thailand|philippines|southeast asia/, EUROPE: /europe|\buk\b|united kingdom|germany|france|netherlands|belgium/, US: /\busa?\b|united states|america/, MIDDLE_EAST: /\buae\b|dubai|abu dhabi|saudi|qatar|bahrain|\boman\b|kuwait|middle east|\bgcc\b/, AFRICA: /africa|nigeria|kenya|ghana|egypt|tanzania|uganda|rwanda/, LATAM: /latam|latin america|brazil|mexico|argentina|colombia|chile|peru/ };
    // 25 Sep: a startup market of 'global' / 'worldwide' now matches ANY investor scope, mirroring GLOBAL on the investor side.
    // Before this, 'Global' matched no region and fell through to the INDIA default below, so global startups were sent to India-only funds (MentorCloud -> IAN Alpha, 24 Sep) and were invisible to US/EUROPE/SEA-scoped funds.
    if (/\bglobal\b|worldwide|\bany\b/.test(g)) { gate('geography', true, 'startup market is global (' + (st.geography || '') + '); matches any scope'); }
    else {
    const regions = Object.keys(REGION).filter(function (k) { return REGION[k].test(g); });
    if (!regions.length) { regions.push('INDIA'); }
    const ok = scope.indexOf('NON_INDIA') >= 0 ? regions.some(function (r) { return r !== 'INDIA'; }) : regions.some(function (r) { return scope.indexOf(r) >= 0; });
    gate('geography', ok, 'investor invests in ' + scope.join('/') + '; startup market ' + (st.geography || 'unknown'));
    }
  }
  const failed = gates.filter(function (g) { return !g.ok; }); const pass = failed.length === 0;
  return { pass: pass, match_type: pass ? 'Exact match' : 'Not per strategy: ' + failed.map(function (g) { return g.gate + ' - ' + g.why; }).join('; '), failed: failed.map(function (g) { return g.gate; }), gates: gates };
}
// ===== meetings (latest staircase block) =====
const NOW = new Date();
function isHdr(row) { return /startup got meetings/i.test(s((row || [])[1])) && /\d/.test(s((row || [])[0])); }
const hdrs = []; for (let i = 0; i < grid.length; i++) { if (isHdr(grid[i])) { hdrs.push(i); } }
if (!hdrs.length) { throw new Error('ABORT: no staircase blocks in meetings sheet'); }
function blockDate(label) { const mm = s(label).match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); if (!mm) { return null; } const a = +mm[1], b = +mm[2], y = +mm[3]; const c = [];
  if (b >= 1 && b <= 12 && a >= 1 && a <= 31) { c.push(new Date(Date.UTC(y, b - 1, a))); } if (a >= 1 && a <= 12 && b >= 1 && b <= 31) { c.push(new Date(Date.UTC(y, a - 1, b))); }
  const past = c.filter(function (d) { return d <= NOW; }); const pool = past.length ? past : c; pool.sort(function (x, z) { return z - x; }); return pool[0] || null; }
let li = hdrs[hdrs.length - 1]; let ld = blockDate(s(grid[li][0]));
for (const i of hdrs) { const d = blockDate(s(grid[i][0])); if (d && (!ld || d > ld)) { ld = d; li = i; } }
const stair = {};
for (let i = li + 1; i < grid.length; i++) { const row = grid[i] || []; if (isHdr(row)) { break; } const mm = s(row[1]).match(/^(\d+)\s*meetings?/i); if (!mm) { if (Object.keys(stair).length) { break; } else { continue; } }
  const n = parseInt(mm[1], 10); for (let j = 2; j < row.length; j++) { const nm = s(row[j]); if (!nm) { continue; } const k = nz(nm); if (stair[k] === undefined || n > stair[k]) { stair[k] = n; } } }
const MALIAS = { caffeinacoffee: 'caffenacoffee', springbaseai: 'springbaseai', vold: 'voldenergy' };
const meetCache = {};
function meetingsFor(name) { if (meetCache[name] !== undefined) { return meetCache[name]; } const k = nz(name); let best = null; for (const sk of Object.keys(stair)) { const kk = MALIAS[sk] || sk; const hit = kk === k || (kk.length >= 4 && k.length >= 4 && (kk.indexOf(k) === 0 || k.indexOf(kk) === 0)); if (hit && (best === null || stair[sk] > best)) { best = stair[sk]; } } meetCache[name] = best === null ? 0 : best; return meetCache[name]; }

// ===== dates (IST) =====
function istDate(d) { return new Date(d.getTime() + 330 * 60000).toISOString().slice(0, 10); }
const TODAY = istDate(NOW);
function addDays(iso, n) { const d = new Date(iso + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function dow(iso) { return new Date(iso + 'T00:00:00Z').getUTCDay(); }
function monday(iso) { const w = dow(iso); return addDays(iso, w === 0 ? -6 : 1 - w); }
const DAYS = []; { let d = addDays(TODAY, 1); while (DAYS.length < HORIZON_WEEKDAYS) { if (dow(d) >= 1 && dow(d) <= 5) { DAYS.push(d); } d = addDays(d, 1); } }

// ===== lookups =====
const critBy = {}; C.forEach(function (c) { const k = nz(c.investor); if (k && !critBy[k]) { critBy[k] = c; } });
const profBy = {}; SP.forEach(function (p) { profBy[nz(p.startup)] = p; });
const stBy = {}; ST.forEach(function (r) { if (s(r.startup)) { stBy[nz(r.startup)] = r; } });
const invBy = {}; INV.forEach(function (r) { const k = nz(r.investor); if (k && !invBy[k]) { invBy[k] = r; } });
function inboxOf(email) { return s(email).toLowerCase().split(/[,;\s]+/).filter(Boolean).sort().join(','); }
function profileFor(stName) { const p = profBy[nz(stName)], srow = stBy[nz(stName)]; if (!p) { return null; } const o = Object.assign({}, p); if (srow) { o.active = s(srow.active) || o.active; } return o; }
function isPending(c) { return s(c.confirmed).toUpperCase() === 'PENDING'; }
function short(mt) { return s(mt).replace(/^Not per strategy: /, '').slice(0, 220); }

// ===== PIPELINE =====
const ph = (pipe[0] || []).map(s); const PX = {}; ph.forEach(function (h, i) { PX[h] = i; });
['deal_id', 'startup', 'owner', 'investor', 'email', 'cc', 'match_type', 'deal_shared', 'date_shared', 'next_action', 'next_due', 'investor_response', 'pause', 'notes'].forEach(function (h) { if (PX[h] === undefined) { throw new Error('ABORT: PIPELINE column missing ' + h); } });
function colL(i) { let n = i + 1, t = ''; while (n > 0) { const m = (n - 1) % 26; t = String.fromCharCode(65 + m) + t; n = Math.floor((n - 1) / 26); } return t; }
const upd = {}; // rowNumber -> {col: value}
function set(rn, col, val) { (upd[rn] = upd[rn] || {})[col] = val; }
const rows = [];
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || []; const g = function (h) { return s(row[PX[h]]); };
  rows.push({ rn: r + 1, id: g('deal_id'), startup: g('startup'), owner: g('owner'), investor: g('investor'), email: g('email'), match_type: g('match_type'), sent: /^yes$/i.test(g('deal_shared')), date_shared: g('date_shared').slice(0, 10), na: g('next_action'), due: g('next_due').slice(0, 10), resp: g('investor_response'), ms: g('meeting_scheduled'), md: g('meeting_date'), mh: g('meetings_held'), paused: /^yes$/i.test(g('pause')), notes: g('notes') }); }
const TAG = 'ENGINE ' + TODAY;
const DROP_NA = 'DROPPED - not per strategy (engine)', HOLD_NA = 'HOLD - investor criteria under review (engine)';
const FLAG_NA = 'FLAGGED - off thesis but has prior contact - human review';
const sum = { today: TODAY, staircase_block: s(grid[li][0]), pipeline_rows: rows.length, queued_checked: 0, followups_checked: 0, dropped_queued: 0, held_queued: 0, stopped_followups: 0, held_followups: 0, released_queued: 0, released_followups: 0, redated_same_day_cap: 0, no_criteria: {}, no_profile: {}, drop_by_gate: {}, drop_by_investor: {}, added: 0, added_by_startup: {}, unplaced_candidates: 0, tracker_rows: 0, tracker_investors: 0, tracker_excluded_pairs: 0, dup_groups_after: 0 };
sum.ceilings_on_file = C.filter(function (c) { return num(c.round_max_cr) !== null; }).length;
const toAllocate = []; // {kind:'release'|'redate'|'new', ...}

// ---- Part A: evaluate existing rows ----
for (const x of rows) {
  const c = critBy[nz(x.investor)], p = profileFor(x.startup);
  const isQueued = !x.sent && !x.paused && x.na === "Initial";
  const isFollow = x.sent && !x.paused && !x.resp && /follow/i.test(x.na);
  // 28 Sep 2026: meeting-paused rows added here. Before this they matched no branch, so no run could ever re-evaluate them -
// which is why Springbase.ai sat blocked for ten days. They now go through evaluate() like any other parked row and are
// released one per startup per round inside the daily/weekly caps, rather than by a bulk unpause.
// Orbo AI's 54 rows are in this set but CANNOT release: STARTUPS active=No, so the startup_active gate fails (user stopped
// Orbo on 22 Sep). That is the guard working, not an oversight - do not special-case it.
const isEngineParked = !x.sent && x.paused && (x.na === DROP_NA || x.na === HOLD_NA || MEET_PAUSED_RE.test(x.na));
  const isEngineHeldFU = x.sent && x.paused && !x.resp && /ENGINE-HOLD-FU/.test(x.notes);
  if (!(isQueued || isFollow || isEngineParked || isEngineHeldFU)) { continue; }
  if (!c) { if (isQueued || isFollow) { sum.no_criteria[x.investor] = (sum.no_criteria[x.investor] || 0) + 1; } continue; }
  if (!p) { if (isQueued || isFollow) { sum.no_profile[x.startup] = (sum.no_profile[x.startup] || 0) + 1; } continue; }
  if (/ENGINE OVERRIDE/i.test(x.notes)) { continue; }
  if (isQueued && meetStop(x.startup)) { set(x.rn, 'pause', 'Yes'); set(x.rn, 'next_action', MEET_NA); set(x.rn, 'notes', (x.notes ? x.notes + ' | ' : '') + TAG + ': paused - startup has ' + meetingsFor(x.startup) + ' meetings (7+ rule)'); x.paused = true; sum.paused_meetings7 = (sum.paused_meetings7 || 0) + 1; continue; }
  if (isEngineParked && meetStop(x.startup)) { continue; }
  const ev = evaluate(c, p, { meetings: meetingsFor(x.startup) });
  const pend = isPending(c);
  if (isQueued || isFollow) {
    if (isQueued) { sum.queued_checked++; } else { sum.followups_checked++; }
    if (ev.pass && !pend) { continue; }
    if (ev.pass && pend) { continue; } // pending investor but fits the draft criteria: keep going
    ev.failed.forEach(function (gname) { sum.drop_by_gate[gname] = (sum.drop_by_gate[gname] || 0) + 1; });
    sum.drop_by_investor[x.investor] = (sum.drop_by_investor[x.investor] || 0) + 1;
    set(x.rn, 'pause', 'Yes'); x.paused = true;
    if (isQueued) {
      // 25 Sep: never silently DROP a row that already produced a conversation. A criteria change must not discard
      // a relationship a human created. Eight confirmed cases were dropped after a real meeting (Koncite, Fire Armor x
      // BlueHill 21 Jan, Glazia x Transition 20 Jan, GroCliq x BDev 19 Jan, Orbis x AWE 30 Sep 25, Pixelence and Ulai x
      // Speciale Mar, Pixelence x Michele). These are still paused so nothing sends, but they are labelled for a human.
      const hasHistory = !!(x.resp || x.ms || x.md || (x.mh && x.mh !== '0'));
      if (hasHistory && !pend) {
        set(x.rn, 'next_action', FLAG_NA);
        set(x.rn, 'match_type', ev.match_type.slice(0, 480));
        set(x.rn, 'notes', (x.notes ? x.notes + ' | ' : '') + TAG + ': FLAGGED not dropped - off thesis now, but this pair already has history (' + [x.resp ? 'response' : '', x.ms || x.md ? 'meeting' : '', (x.mh && x.mh !== '0') ? x.mh + ' meetings held' : ''].filter(Boolean).join(', ') + '). A human should decide, not the engine. Reason: ' + short(ev.match_type));
        sum.flagged_with_history = (sum.flagged_with_history || 0) + 1;
        (sum.flagged_list = sum.flagged_list || []).push(x.startup + ' x ' + x.investor);
        continue;
      }
